<div class="modal-backdrop" id="create-modal" onclick="backdropClose(event,this)"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="create-title"><form method="POST" enctype="multipart/form-data" action="{{ route('admin.layanan.store') }}">@csrf<div class="modal-head"><h2 id="create-title">Tambah Layanan</h2><button class="close" type="button" onclick="closeModal('create-modal')">×</button></div><div class="modal-body"><div class="grid"><div class="field"><label>Nama layanan</label><input name="nama_layanan" value="{{ old('nama_layanan') }}" required></div><div class="field"><label>Variasi</label><input name="variasi" value="{{ old('variasi') }}"></div><div class="field"><label>Harga (Rp)</label><input type="text" inputmode="numeric" data-price-format name="harga" value="{{ old('harga') }}" placeholder="Contoh: 1.450.000" required></div><div class="field"><label>Status</label><select name="status"><option value="Aktif" @selected(old('status','Aktif')==='Aktif')>Aktif</option><option value="Nonaktif" @selected(old('status')==='Nonaktif')>Nonaktif</option></select></div><div class="field full"><label>Deskripsi</label><textarea name="deskripsi" rows="3">{{ old('deskripsi') }}</textarea></div><div class="field full"><label>Foto layanan</label><input type="file" name="foto" accept="image/jpeg,image/png,image/webp"><small>Format JPG, PNG, atau WEBP. Maksimal 4 MB.</small></div><div class="field full"><label>Tampilkan sebagai unggulan?</label><div class="featured-choice"><label><input style="width:auto" type="radio" name="unggulan" value="1" @checked(old('unggulan','0')==='1') required> Unggulan</label><label><input style="width:auto" type="radio" name="unggulan" value="0" @checked(old('unggulan','0')==='0') required> Tidak</label></div></div></div></div><div class="modal-foot"><button class="btn btn-light" type="button" onclick="closeModal('create-modal')">Batal</button><button class="btn" type="submit">Simpan Layanan</button></div></form></section></div>
<div class="modal-backdrop" id="edit-modal" onclick="backdropClose(event,this)"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="edit-title"><form id="edit-form" method="POST" enctype="multipart/form-data">@csrf @method('PUT')<div class="modal-head"><h2 id="edit-title">Ubah Layanan</h2><button class="close" type="button" onclick="closeModal('edit-modal')">×</button></div><div class="modal-body"><div class="grid"><div class="field"><label>Nama layanan</label><input id="edit-name" name="nama_layanan" required></div><div class="field"><label>Variasi</label><input id="edit-variation" name="variasi"></div><div class="field"><label>Harga (Rp)</label><input id="edit-price" type="text" inputmode="numeric" data-price-format name="harga" placeholder="Contoh: 1.450.000" required></div><div class="field"><label>Status</label><select id="edit-status" name="status"><option>Aktif</option><option>Nonaktif</option></select></div><div class="field full"><label>Deskripsi</label><textarea id="edit-description" name="deskripsi" rows="3"></textarea></div><div class="field full"><label>Foto layanan</label><img id="edit-photo-preview" alt="Foto layanan saat ini" style="display:none;max-width:150px;max-height:100px;object-fit:cover;border-radius:8px;margin-bottom:8px"><input type="file" name="foto" accept="image/jpeg,image/png,image/webp"><small>Kosongkan jika tidak ingin mengganti foto. Maksimal 4 MB.</small></div><div class="field full"><label>Tampilkan sebagai unggulan?</label><div class="featured-choice"><label><input style="width:auto" type="radio" name="unggulan" value="1" required> Unggulan</label><label><input style="width:auto" type="radio" name="unggulan" value="0" required> Tidak</label></div></div></div></div><div class="modal-foot"><button class="btn btn-light" type="button" onclick="closeModal('edit-modal')">Batal</button><button class="btn" type="submit">Simpan Perubahan</button></div></form></section></div>
<script>function formatHarga(value){const digits=String(value??'').replace(/\D/g,'');return digits.replace(/\B(?=(\d{3})+(?!\d))/g,'.')}document.querySelectorAll('[data-price-format]').forEach(input=>{input.value=formatHarga(input.value);input.addEventListener('input',()=>{input.value=formatHarga(input.value)})});function openModal(id){document.getElementById(id).classList.add('show')}function closeModal(id){document.getElementById(id).classList.remove('show')}function backdropClose(e,el){if(e.target===el)el.classList.remove('show')}function editLayanan(b){const d=b.dataset;document.getElementById('edit-form').action=d.action;document.getElementById('edit-name').value=d.name;document.getElementById('edit-variation').value=d.variation;document.getElementById('edit-price').value=formatHarga(d.price);document.getElementById('edit-status').value=d.status;document.getElementById('edit-description').value=d.description;document.querySelector('#edit-form input[name="unggulan"][value="'+d.featured+'"]').checked=true;const preview=document.getElementById('edit-photo-preview');preview.src=d.photo;preview.style.display=d.photo?'block':'none';openModal('edit-modal')}document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.modal-backdrop.show').forEach(m=>m.classList.remove('show'))});@if($errors->any())openModal('create-modal');@endif</script></body></html>
